CREATE TABLE users(id BIGINT PRIMARY KEY,tenant_id BIGINT);
CREATE TABLE projects(id BIGINT PRIMARY KEY,tenant_id BIGINT,cohort_id BIGINT);
CREATE TABLE cohorts(id BIGINT PRIMARY KEY,tenant_id BIGINT,name VARCHAR(255));
CREATE TABLE teams(id BIGINT PRIMARY KEY,created_at TIMESTAMP NOT NULL,created_by BIGINT,is_active BOOLEAN NOT NULL,updated_at TIMESTAMP NOT NULL,updated_by BIGINT,code VARCHAR(100),name VARCHAR(255),tenant_id BIGINT,project_id BIGINT,mentor_id BIGINT,mission VARCHAR(2000),definition_of_done VARCHAR(2000),primary_channel VARCHAR(255),core_hours VARCHAR(255),conflict_resolution VARCHAR(2000));
CREATE TABLE team_members(id BIGINT PRIMARY KEY,created_at TIMESTAMP NOT NULL,created_by BIGINT,is_active BOOLEAN NOT NULL,updated_at TIMESTAMP NOT NULL,updated_by BIGINT,team_id BIGINT,user_id BIGINT,project_role VARCHAR(32),participation_status VARCHAR(32),joined_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE project_members(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created_at TIMESTAMP NOT NULL,created_by BIGINT,is_active BOOLEAN NOT NULL,updated_at TIMESTAMP NOT NULL,updated_by BIGINT,team_id BIGINT,member_id BIGINT,member_role VARCHAR(30));
CREATE TABLE workspaces(id BIGINT PRIMARY KEY,team_id BIGINT NOT NULL,project_id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(100),CONSTRAINT old_workspace_team FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE workspace_audits(id BIGINT PRIMARY KEY,workspace_id BIGINT,team_id BIGINT,project_id BIGINT,tenant_id BIGINT,before_json VARCHAR(1000),after_json VARCHAR(1000));
CREATE TABLE workspace_creation_requests(id BIGINT PRIMARY KEY,workspace_id BIGINT,response_json VARCHAR(1000));
CREATE TABLE milestones(milestone_id UUID PRIMARY KEY,project_id UUID NOT NULL,tenant_id UUID NOT NULL,title VARCHAR(120),deadline TIMESTAMP WITH TIME ZONE);
CREATE TABLE milestone_checklist_items(item_id UUID PRIMARY KEY,milestone_id UUID NOT NULL,content VARCHAR(255),CONSTRAINT old_checklist_milestone FOREIGN KEY(milestone_id) REFERENCES milestones(milestone_id));
CREATE TABLE milestone_audit_logs(audit_id UUID PRIMARY KEY,milestone_id UUID,project_id UUID NOT NULL,tenant_id UUID NOT NULL,details_json VARCHAR(1000));
CREATE TABLE milestone_risk_alerts(id UUID PRIMARY KEY,milestone_id UUID,project_id UUID NOT NULL,tenant_id BIGINT NOT NULL);
CREATE TABLE task_alert_project_links(id UUID PRIMARY KEY,project_id BIGINT,tenant_id BIGINT);
CREATE TABLE project_templates(id BIGINT PRIMARY KEY,title VARCHAR(255) NOT NULL,content_json VARCHAR(1000) NOT NULL,tenant_id BIGINT NOT NULL,status VARCHAR(30) DEFAULT 'DRAFT' NOT NULL,review_status VARCHAR(30) DEFAULT 'NOT_SUBMITTED' NOT NULL);
CREATE TABLE sprint_backlog(sprint_backlog_id BIGINT PRIMARY KEY,title VARCHAR(255),assignee_project_member_id BIGINT);
